178	\begin{theorem}[Quantum soundness of the low individual degree test]\label{thm:main-formal}
179		\lean{MIPStarRE.LDT.Test.mainFormal}
180		\leanok
181		\uses{def:low-individual-degree-test, def:projective-strategy, def:polymeasurements, def:simeq}
182		Let $(\psi, A^{\mathrm A}, B^{\mathrm A}, L^{\mathrm A},
183		A^{\mathrm B}, B^{\mathrm B}, L^{\mathrm B})$ be a projective strategy that
184		passes the $(m,q,d)$ low individual degree test with probability at least
185		$1-\eps$. Let \(k>0\) be an integer with \(k \ge 400md\), and set
186		\[
187			\nu = 100000 k^2 m^4\left(\eps^{1/40000} + (d/q)^{1/40000} + e^{-k/(2560000m^2)}\right).
188		\]
189		Then there exist projective measurements
190		$G^{\mathrm A}, G^{\mathrm B} \in \polymeas{m}{q}{d}$ with the following
191		properties:
192		\begin{enumerate}
193			\item on average over $u \sim \F_q^m$,
194			      \[
195				      A_a^{\mathrm A,u} \ot I \simeq_\nu I \ot G^{\mathrm B}_{[g(u)=a]},
196				      \qquad
197				      I \ot A_a^{\mathrm B,u} \simeq_\nu G^{\mathrm A}_{[g(u)=a]} \ot I;
198			      \]
199			\item
200			      \[
201				      G_g^{\mathrm A} \ot I \simeq_\nu I \ot G_g^{\mathrm B}.
202			      \]
203		\end{enumerate}
204	\end{theorem}
205	\begin{proof}
206		\leanok
207		\uses{prop:main-formal-source-reduction, prop:main-formal-source-small-error}
208		The saturated-error branch is formalized by
209		\texttt{mainFormal\_trivial\_witness}.  The remaining branch is the
210		small-error source-boundary proposition
211		Proposition~\ref{prop:main-formal-source-small-error}.  The
212		factor \(400\) and the nonzero sampling condition are the corrected source
213		boundaries recorded in \cite{gap:issue-906-main-formal-k-bound} and
214		\cite{gap:issue-422-main-formal-zero-k-boundary}.
215	\end{proof}
