239	\begin{theorem}[Complete-measurement linear-triangle bound]
240	\label{thm:main-formal-linear-triangle}
241		\lean{MIPStarRE.LDT.Test.main_formal_linear_triangle_bound}
242		\leanok
243		\uses{thm:main-formal, lem:complete-measurement-consistency-triangle}
244		Let $(\psi,A^{\mathrm A},B^{\mathrm A},L^{\mathrm A},
245		A^{\mathrm B},B^{\mathrm B},L^{\mathrm B})$ be a projective strategy that
246		passes the $(m,q,d)$ low individual degree test with probability at least
247		$1-\eps$.  Let $k>0$ be an integer with $k\ge 400md$, and set
248		\[
249			T=10000 k^{1/4}m^{1/2}\left(
250				\eps^{1/8192}+(d/q)^{1/8192}
251				+e^{-k/(640000m^2)}\right),
252			\qquad \nu_{\mathrm{lin}}=\min\{1,T\}.
253		\]
254		Then there are projective measurements
255		$Q^{\mathrm A},Q^{\mathrm B}\in\polymeas{m}{q}{d}$ such that, on average
256		over $u\sim\F_q^m$,
257		\[
258			A_a^{\mathrm A,u}\ot I\simeq_{\nu_{\mathrm{lin}}}
259				I\ot Q^{\mathrm B}_{[g(u)=a]},
260			\qquad
261			I\ot A_a^{\mathrm B,u}\simeq_{\nu_{\mathrm{lin}}}
262				Q^{\mathrm A}_{[g(u)=a]}\ot I,
263		\]
264		and
265		\[
266			Q_g^{\mathrm A}\ot I\simeq_{\nu_{\mathrm{lin}}}
267				I\ot Q_g^{\mathrm B}.
268		\]
269		This is a Lean-only quantitative improvement obtained from the source proof.
270		It does not replace or relabel Theorem~\ref{thm:main-formal}.
271	\end{theorem}
272	\begin{proof}
273		\leanok
274		Write $I$ for the main-induction error, $s=2I$, and
275		$z=6s+9\eps+md/q$.  Lemma~\ref{lem:complete-measurement-consistency-triangle}
276		gives this linear $z$ in place of the square-root triangle loss.  The existing
277		projectivization, completion, and repaired line-169 construction has point
278		error at most $2221z^{1/8}$ and full-polynomial error at most the same
279		quantity when $z\le 1$.  The induction estimate gives
280		\[
281			z\le 120010k^2m^4\left(
282				\eps^{1/1024}+(d/q)^{1/1024}+e^{-k/(80000m^2)}\right).
283		\]
284		The certificates $120010\le(9/2)^8$ and
285		$2221(9/2)\le10000$, followed by three square-root envelope steps, give
286		$2221z^{1/8}\le T$.  If $T\ge1$, normalized consistency defects are at most
287		one, giving the capped branch independently of the old error.
288	\end{proof}
