290	\begin{proposition}[Comparison of the two capped final errors]
291	\label{prop:main-formal-linear-triangle-comparison}
292		\lean{MIPStarRE.LDT.Test.mainFormalLinearTriangleError_le_min_mainFormalError}
293		\lean{MIPStarRE.LDT.Test.mainFormalLinearTriangleError_lt_min_mainFormalError}
294		\leanok
295		Assume $\eps\ge0$ and $k>0$.  With $\nu_{\mathrm{lin}}$ as above and
296		$\nu_{\mathrm{base}}$ from
297		Proposition~\ref{prop:main-formal-explicit-baseline},
298		\[
299			\nu_{\mathrm{lin}}\le\min\{1,\nu_{\mathrm{base}}\}.
300		\]
301		If $\nu_{\mathrm{base}}<1$, then the inequality is strict.  More precisely,
302		in that branch the formal scalar proof establishes
303		$10T\le\nu_{\mathrm{base}}$; the exponential summand makes $T>0$.
304	\end{proposition}
305	\begin{proof}
306		\leanok
307		When the old error is at least one, both sides are capped by one.  Otherwise
308		$0\le\eps\le1$ and $d/q\le1$.  Monotonicity of real powers and the exponential
309		tail, together with $k^{1/4}\le k^2$ and $m^{1/2}\le m^4$, gives the stated
310		factor-ten comparison.
311	\end{proof}
